def right_count(xs, ys, t):
    right = 0
    for i in range(len(xs)):
        if (xs[i] >= t) == (ys[i] == 1):
            right = right + 1
    return right

def fit_and_score(train_x, train_y, test_x, test_y):
    best_t = 0
    best_right = -1
    for t in range(11):
        r = right_count(train_x, train_y, t)
        if r > best_right:
            best_t = t
            best_right = r
    return (best_t, right_count(test_x, test_y, best_t))
